=== useFilterDrawerState.ts ===
     1	import { useLayoutEffect, useState } from 'react';
     2	
     3	export type PendingRefinements = Record<string, string[]>;
     4	
     5	type UseFilterDrawerStateParams = {
     6	  /** Whether the filter drawer is currently open — pending state resyncs from the
     7	   *  currently-applied filters every time this transitions to true. */
     8	  isOpen: boolean;
     9	  /**
    10	   * The category ID currently reflected in the URL — used as the initial pending
    11	   * category selection each time the drawer opens. Pass `params.categoryId` for a
    12	   * standard single-category page, or `undefined` when no sub-category is active.
    13	   */
    14	  categoryId?: string;
    15	  /** The currently-applied refinements — pass searchParams.refine (the real URL-derived
    16	   *  ground truth), NOT productSearchResult.selectedRefinements (the SFCC API field that
    17	   *  only reflects what the backend chose to echo back, which is often incomplete).
    18	   *  Values may be a pipe-separated string ('Black|White'), an array, or a number. */
    19	  selectedRefinements?: Record<string, string | number | (string | number)[] | undefined>;
    20	};
    21	
    22	type UseFilterDrawerStateReturn = {
    23	  /** The category currently pending selection in the drawer, or undefined if none. */
    24	  pendingCategoryId: string | undefined;
    25	  /** Replaces the pending category — use to set a new selection or clear (pass undefined). */
    26	  setPendingCategoryId: (id: string | undefined) => void;
    27	  pendingRefine: PendingRefinements;
    28	  setValues: (attributeId: string, values: string[]) => void;
    29	  removeValue: (attributeId: string, value: string) => void;
    30	  clearAll: () => void;
    31	  /** Re-derives pendingRefine from a (possibly different) selectedRefinements snapshot —
    32	   *  same parsing the drawer-open resync uses. For a caller that reverts a pending category
    33	   *  change back to the currently-applied category (e.g. removing the category chip): that
    34	   *  category change already cleared pendingRefine via clearAll, so reverting it must also
    35	   *  restore whatever refine is actually still applied, not leave the buffer empty. */
    36	  resyncPendingRefine: (selectedRefinements?: UseFilterDrawerStateParams['selectedRefinements']) => void;
    37	};
    38	
    39	/**
    40	 * Parses a searchParams.refine-shaped object into the buffered PendingRefinements shape —
    41	 * split out so both the drawer-open resync effect and a caller-triggered resync
    42	 * (resyncPendingRefine) share one implementation.
    43	 */
    44	const parseSelectedRefinements = (
    45	  selectedRefinements: UseFilterDrawerStateParams['selectedRefinements'],
    46	): PendingRefinements => {
    47	  const initial: PendingRefinements = {};
    48	  Object.entries(selectedRefinements ?? {}).forEach(([attributeId, rawValue]) => {
    49	    if (attributeId === 'cgid' || rawValue == null) return;
    50	    // searchParams.refine values can be arrays (from buildAppliedRefine), pipe-separated
    51	    // strings ('Black|White' — SFCC URL encoding), or plain numbers. Handle all three so
    52	    // the resync works correctly regardless of whether the value was round-tripped through
    53	    // the URL parser or set directly.
    54	    const values: string[] = Array.isArray(rawValue) ? rawValue.map(String) : String(rawValue).split('|');
    55	    if (values.length > 0 && values[0] !== '') initial[attributeId] = values;
    56	  });
    57	  return initial;
    58	};
    59	
    60	/**
    61	 * Buffers SFCC-847 filter-drawer selections (category + every refinement facet) in local
    62	 * state instead of applying each click straight to the URL/product grid. Resyncs from the
    63	 * page's currently-applied filters every time the drawer opens, so a value chosen and then
    64	 * abandoned (drawer closed without pressing APPLY) never reaches the URL, and reopening
    65	 * after a previous APPLY reflects reality rather than stale local state.
    66	 *
    67	 * @returns pending category/refinement selections plus mutators. The caller is responsible
    68	 * for actually applying them (navigating) when the shopper presses APPLY.
    69	 */
    70	export const useFilterDrawerState = ({
    71	  isOpen,
    72	  categoryId,
    73	  selectedRefinements,
    74	}: UseFilterDrawerStateParams): UseFilterDrawerStateReturn => {
    75	  const [pendingCategoryId, setPendingCategoryId] = useState<string | undefined>(categoryId);
    76	  const [pendingRefine, setPendingRefine] = useState<PendingRefinements>({});
    77	
    78	  // useLayoutEffect (not useEffect) — runs synchronously after DOM commit and before the
    79	  // browser paints. This prevents the visible flash of stale checkbox state that useEffect
    80	  // causes: with useEffect the drawer renders once with the previous pendingRefine (user
    81	  // briefly sees wrong checked state), then the effect fires and corrects it. The filter
    82	  // drawer is always closed during SSR so the isOpen guard means this body never runs
    83	  // server-side — the layout-effect SSR warning does not apply here.
    84	  useLayoutEffect(() => {
    85	    if (!isOpen) return;
    86	    setPendingRefine(parseSelectedRefinements(selectedRefinements));
    87	    setPendingCategoryId(categoryId);
    88	    // Resync is keyed on `isOpen` alone. `categoryId`/`selectedRefinements` change on every
    89	    // navigation — including the one APPLY itself triggers — so including them here would
    90	    // re-run this effect right after APPLY and stomp the just-applied selection straight
    91	    // back to whatever the next render resolves it to.
    92	  }, [isOpen]);
    93	
    94	  const resyncPendingRefine = (nextSelectedRefinements?: UseFilterDrawerStateParams['selectedRefinements']) => {
    95	    setPendingRefine(parseSelectedRefinements(nextSelectedRefinements));
    96	  };
    97	
    98	  const setValues = (attributeId: string, values: string[]) => {
    99	    setPendingRefine((prev) => {
   100	      if (values.length === 0) {
   101	        const { [attributeId]: _removed, ...rest } = prev;
   102	        return rest;
   103	      }
   104	      return { ...prev, [attributeId]: values };
   105	    });
   106	  };
   107	
   108	  const removeValue = (attributeId: string, value: string) => {
   109	    setPendingRefine((prev) => {
   110	      const next = (prev[attributeId] ?? []).filter((v) => v !== value);
   111	      if (next.length === 0) {
   112	        const { [attributeId]: _removed, ...rest } = prev;
   113	        return rest;
   114	      }
   115	      return { ...prev, [attributeId]: next };
   116	    });
   117	  };
   118	
   119	  const clearAll = () => setPendingRefine({});
   120	
   121	  return {
   122	    pendingCategoryId,
   123	    setPendingCategoryId,
   124	    pendingRefine,
   125	    setValues,
   126	    removeValue,
   127	    clearAll,
   128	    resyncPendingRefine,
   129	  };
   130	};
   131	
   132	export type AppliedRefine = Record<string, string | number | (string | number)[]>;
   133	
   134	/**
   135	 * Merges buffered facet selections into the page's real `searchParams.refine` object —
   136	 * the pure computation behind the drawer's APPLY handler, split out so it's testable
   137	 * without a component or navigation. Every attribute this drawer manages (every non-cgid
   138	 * attributeId SFCC currently returns as a refinement) is fully overwritten from
   139	 * `pendingRefine` — including being deleted if the shopper unticked it back to empty —
   140	 * while any attribute this drawer does not manage (e.g. StoreInventoryFilter's `ilids`) is
   141	 * left exactly as it was in `currentRefine`.
   142	 *
   143	 * @returns a new refine object; never mutates `currentRefine`.
   144	 */
   145	export const buildAppliedRefine = (
   146	  currentRefine: AppliedRefine,
   147	  managedAttributeIds: string[],
   148	  pendingRefine: PendingRefinements,
   149	): AppliedRefine => {
   150	  const nextRefine: AppliedRefine = { ...currentRefine };
   151	  const managedSet = new Set(managedAttributeIds);
   152	  managedSet.forEach((attributeId) => {
   153	    delete nextRefine[attributeId];
   154	  });
   155	  // Only write back attributes this drawer manages — unmanaged ones (e.g. ilids) are already
   156	  // preserved from the { ...currentRefine } spread above and must not be overwritten with the
   157	  // array-converted form that parseSelectedRefinements produces.
   158	  Object.entries(pendingRefine).forEach(([attributeId, values]) => {
   159	    if (managedSet.has(attributeId)) {
   160	      nextRefine[attributeId] = values;
   161	    }
   162	  });
   163	  return nextRefine;
   164	};

=== useFilterDrawerState.test.ts ===
     1	import { describe, test, expect } from 'vitest';
     2	import { renderHook, act } from '@testing-library/react';
     3	import { useFilterDrawerState, buildAppliedRefine } from './useFilterDrawerState';
     4	
     5	describe('useFilterDrawerState', () => {
     6	  test('resyncs pending state from currently-applied filters when the drawer opens', () => {
     7	    const { result, rerender } = renderHook(
     8	      ({ isOpen }) =>
     9	        useFilterDrawerState({
    10	          isOpen,
    11	          categoryId: 'clothing',
    12	          selectedRefinements: { c_size: 'S|M', cgid: 'clothing' },
    13	        }),
    14	      { initialProps: { isOpen: false } },
    15	    );
    16	
    17	    expect(result.current.pendingRefine).toEqual({});
    18	
    19	    rerender({ isOpen: true });
    20	
    21	    // cgid is excluded — category is tracked separately via pendingCategoryId, not as a
    22	    // refinement value, matching product-list/index.tsx's own toggleFilter-vs-navigation split.
    23	    expect(result.current.pendingRefine).toEqual({ c_size: ['S', 'M'] });
    24	    expect(result.current.pendingCategoryId).toBe('clothing');
    25	  });
    26	
    27	  test('setValues replaces the full value set for an attribute (checkbox group onChange)', () => {
    28	    const { result } = renderHook(() =>
    29	      useFilterDrawerState({ isOpen: true, categoryId: 'clothing', selectedRefinements: {} }),
    30	    );
    31	
    32	    act(() => result.current.setValues('c_refinementColor', ['Black', 'White']));
    33	    expect(result.current.pendingRefine).toEqual({ c_refinementColor: ['Black', 'White'] });
    34	
    35	    act(() => result.current.setValues('c_refinementColor', []));
    36	    expect(result.current.pendingRefine).toEqual({});
    37	  });
    38	
    39	  test('removeValue drops a single value without touching other attributes', () => {
    40	    const { result } = renderHook(() =>
    41	      useFilterDrawerState({ isOpen: true, categoryId: 'clothing', selectedRefinements: {} }),
    42	    );
    43	
    44	    act(() => {
    45	      result.current.setValues('c_refinementColor', ['Black', 'White']);
    46	      result.current.setValues('c_size', ['S']);
    47	    });
    48	
    49	    act(() => result.current.removeValue('c_refinementColor', 'Black'));
    50	
    51	    expect(result.current.pendingRefine).toEqual({ c_refinementColor: ['White'], c_size: ['S'] });
    52	  });
    53	
    54	  test('removeValue clears the attribute key entirely once its last value is removed', () => {
    55	    const { result } = renderHook(() =>
    56	      useFilterDrawerState({ isOpen: true, categoryId: 'clothing', selectedRefinements: {} }),
    57	    );
    58	
    59	    act(() => result.current.setValues('c_size', ['S']));
    60	    act(() => result.current.removeValue('c_size', 'S'));
    61	
    62	    expect(result.current.pendingRefine).toEqual({});
    63	  });
    64	
    65	  test('clearAll resets every pending refinement but leaves pendingCategoryId untouched', () => {
    66	    const { result } = renderHook(() =>
    67	      useFilterDrawerState({ isOpen: true, categoryId: 'clothing', selectedRefinements: {} }),
    68	    );
    69	
    70	    act(() => {
    71	      result.current.setValues('c_size', ['S']);
    72	      result.current.setPendingCategoryId('dresses');
    73	    });
    74	
    75	    act(() => result.current.clearAll());
    76	
    77	    expect(result.current.pendingRefine).toEqual({});
    78	    expect(result.current.pendingCategoryId).toBe('dresses');
    79	  });
    80	
    81	  test('resyncPendingRefine restores pendingRefine from a given selectedRefinements snapshot on demand', () => {
    82	    const { result } = renderHook(() =>
    83	      useFilterDrawerState({ isOpen: true, categoryId: 'clothing', selectedRefinements: {} }),
    84	    );
    85	
    86	    // Simulates a category change (clearAll via handleCategoryChange) followed by the
    87	    // shopper reverting it via the category chip's onRemove — pendingRefine must come back
    88	    // from the real applied refine, not stay empty.
    89	    act(() => result.current.clearAll());
    90	    expect(result.current.pendingRefine).toEqual({});
    91	
    92	    act(() => result.current.resyncPendingRefine({ c_refinementColor: 'Black|White', cgid: 'clothing' }));
    93	
    94	    expect(result.current.pendingRefine).toEqual({ c_refinementColor: ['Black', 'White'] });
    95	  });
    96	
    97	  test('buffers selections across several facet groups simultaneously without them interfering', () => {
    98	    const { result } = renderHook(() =>
    99	      useFilterDrawerState({ isOpen: true, categoryId: 'tops', selectedRefinements: {} }),
   100	    );
   101	
   102	    act(() => {
   103	      result.current.setValues('c_refinementColor', ['Blue', 'Green']);
   104	      result.current.setValues('c_size', ['0', '1']);
   105	      result.current.setValues('c_material', ['Cotton']);
   106	      result.current.setPendingCategoryId('tops');
   107	    });
   108	
   109	    expect(result.current.pendingRefine).toEqual({
   110	      c_refinementColor: ['Blue', 'Green'],
   111	      c_size: ['0', '1'],
   112	      c_material: ['Cotton'],
   113	    });
   114	
   115	    // Removing one Colour value doesn't disturb Size or Material's own buffered selections.
   116	    act(() => result.current.removeValue('c_refinementColor', 'Blue'));
   117	    expect(result.current.pendingRefine).toEqual({
   118	      c_refinementColor: ['Green'],
   119	      c_size: ['0', '1'],
   120	      c_material: ['Cotton'],
   121	    });
   122	  });
   123	});
   124	
   125	describe('buildAppliedRefine', () => {
   126	  test('overwrites every managed attribute from pendingRefine and leaves unmanaged ones untouched', () => {
   127	    // Real SFCC-847 shape: cgid=tops already applied via a previous category navigation,
   128	    // c_refinementColor=Blue already applied from a previous APPLY, and ilids (store
   129	    // inventory — not one of this drawer's facet groups at all) already applied too.
   130	    const currentRefine = { cgid: 'tops', c_refinementColor: 'Blue', ilids: 'store123' };
   131	    const managedAttributeIds = ['c_refinementColor', 'c_size', 'c_material'];
   132	    const pendingRefine = {
   133	      c_refinementColor: ['Blue', 'Green'],
   134	      c_size: ['0', '1'],
   135	      c_material: ['Cotton'],
   136	    };
   137	
   138	    const result = buildAppliedRefine(currentRefine, managedAttributeIds, pendingRefine);
   139	
   140	    expect(result).toEqual({
   141	      cgid: 'tops',
   142	      ilids: 'store123',
   143	      c_refinementColor: ['Blue', 'Green'],
   144	      c_size: ['0', '1'],
   145	      c_material: ['Cotton'],
   146	    });
   147	  });
   148	
   149	  test('deletes a managed attribute the shopper unticked back to empty', () => {
   150	    // c_size was applied before (from a prior APPLY) but the shopper unticked every Size
   151	    // value in this drawer session — pendingRefine has no c_size key at all, so the real
   152	    // refine must drop it, not carry the stale value forward.
   153	    const currentRefine = { c_refinementColor: 'Blue', c_size: '0|1' };
   154	    const managedAttributeIds = ['c_refinementColor', 'c_size', 'c_material'];
   155	    const pendingRefine = { c_refinementColor: ['Blue'] };
   156	
   157	    const result = buildAppliedRefine(currentRefine, managedAttributeIds, pendingRefine);
   158	
   159	    expect(result).toEqual({ c_refinementColor: ['Blue'] });
   160	  });
   161	
   162	  test('never mutates the currentRefine object it was given', () => {
   163	    const currentRefine = { c_size: '0' };
   164	    buildAppliedRefine(currentRefine, ['c_size'], { c_size: ['1', '2'] });
   165	
   166	    expect(currentRefine).toEqual({ c_size: '0' });
   167	  });
   168	
   169	  test('does not write back an unmanaged attribute that appears in pendingRefine', () => {
   170	    // ilids sneaking into pendingRefine must not overwrite the currentRefine value.
   171	    const currentRefine = { ilids: 'store123', c_refinementColor: 'Blue' };
   172	    const managedAttributeIds = ['c_refinementColor'];
   173	    const pendingRefine = { c_refinementColor: ['Green'], ilids: ['store456'] };
   174	
   175	    const result = buildAppliedRefine(currentRefine, managedAttributeIds, pendingRefine);
   176	
   177	    expect(result).toEqual({ ilids: 'store123', c_refinementColor: ['Green'] });
   178	  });
   179	});

=== refinementValues.ts ===
     1	import { defineMessages } from 'react-intl';
     2	import type { ShopperSearchTypes } from 'commerce-sdk-isomorphic';
     3	
     4	/**
     5	 * SFCC's own ProductSearchRefinementValue allows any refinement, not just category, to nest
     6	 * child values — flattens the tree into one flat list so a caller (chip-label lookup,
     7	 * checkbox list) sees every nested value, not just the top level.
     8	 */
     9	export const flattenRefinementValues = (
    10	  values: ShopperSearchTypes.ProductSearchRefinementValue[] = [],
    11	): ShopperSearchTypes.ProductSearchRefinementValue[] =>
    12	  values.flatMap((rv) => [rv, ...flattenRefinementValues(rv.values)]);
    13	
    14	// Filter refinement aria-label messages — same as OOTB CheckboxRefinements
    15	const refinementMessages = defineMessages({
    16	  addFilter: { id: 'filter_facets.filters.add_filter_html', defaultMessage: 'Add filter: {label}' },
    17	  removeFilter: { id: 'filter_facets.filters.remove_filter_html', defaultMessage: 'Remove filter: {label}' },
    18	});
    19	
    20	export const ADD_FILTER = refinementMessages.addFilter;
    21	export const REMOVE_FILTER = refinementMessages.removeFilter;

=== refinementValues.test.ts ===
     1	import { describe, test, expect } from 'vitest';
     2	import { flattenRefinementValues } from './refinementValues';
     3	
     4	describe('flattenRefinementValues', () => {
     5	  test('returns an empty array for undefined input', () => {
     6	    expect(flattenRefinementValues(undefined)).toEqual([]);
     7	  });
     8	
     9	  test('returns a flat list unchanged when no value nests children', () => {
    10	    const values = [
    11	      { value: 'Black', label: 'Black', hitCount: 3 },
    12	      { value: 'White', label: 'White', hitCount: 5 },
    13	    ];
    14	
    15	    expect(flattenRefinementValues(values)).toEqual(values);
    16	  });
    17	
    18	  test('includes both a nested group and its children in the flattened result', () => {
    19	    const values = [
    20	      {
    21	        value: 'clothing',
    22	        label: 'Clothing',
    23	        hitCount: 10,
    24	        values: [{ value: '0', label: '0', hitCount: 4 }],
    25	      },
    26	    ];
    27	
    28	    expect(flattenRefinementValues(values)).toEqual([
    29	      values[0],
    30	      { value: '0', label: '0', hitCount: 4 },
    31	    ]);
    32	  });
    33	
    34	  test('flattens multiple levels of nesting', () => {
    35	    const values = [
    36	      {
    37	        value: 'a',
    38	        label: 'A',
    39	        hitCount: 1,
    40	        values: [
    41	          {
    42	            value: 'b',
    43	            label: 'B',
    44	            hitCount: 1,
    45	            values: [{ value: 'c', label: 'C', hitCount: 1 }],
    46	          },
    47	        ],
    48	      },
    49	    ];
    50	
    51	    expect(flattenRefinementValues(values).map((v) => v.value)).toEqual(['a', 'b', 'c']);
    52	  });
    53	});

