import '@testing-library/jest-dom';

// SFCC image-loading/LCP follow-up (2026-09-20) — jsdom has no native IntersectionObserver, so
// without this, `'IntersectionObserver' in window` is false everywhere, and base SFCC's own
// `useIntersectionObserver` hook (@salesforce/retail-react-app/app/hooks/use-intersection-
// observer) falls back to treating every observed element as already-intersecting — a reasonable
// fallback for a genuinely unsupported real browser, but wrong for a test environment: it
// silently makes every "stay lazy until near viewport" behavior act as "immediately visible"
// everywhere, with no way for an individual test to opt out. Confirmed live: this is exactly what
// broke `ZimmProductCard`'s own "without priority, stays lazy" assertion the moment
// `ZimmProductCardMedia`/`ZimmMediaTile` started consuming this hook.
//
// Deliberately minimal and non-firing — it only satisfies the feature-detection check, never
// calls back, so the default in every test stays "not intersecting" (i.e. stays lazy) unless a
// test explicitly drives intersection itself, either by reassigning its own
// `global.IntersectionObserver` (same precedent already used in
// zimmProductGallery/zimmGalleryOverlay's own test files — each file's own reassignment overrides
// this default within that file only, no cross-file leakage) or by mocking the hook module
// directly (zimmMediaTile/zimmProductCardMedia's own test files, plus recommended-products'
// pre-existing precedent).
/* eslint-disable @typescript-eslint/no-empty-function -- no-op stub, see comment above */
class NoopIntersectionObserver {
  observe(): void {}
  unobserve(): void {}
  disconnect(): void {}
  takeRecords(): IntersectionObserverEntry[] {
    return [];
  }
}
/* eslint-enable @typescript-eslint/no-empty-function */

// @ts-expect-error - a deliberately minimal stub, not a full IntersectionObserver implementation
// (same precedent as the local MockIntersectionObserver classes this codebase already has).
global.IntersectionObserver = NoopIntersectionObserver;

// The base hook's own feature-detection checks THREE things, not just the constructor above:
// `'IntersectionObserver' in window`, `'IntersectionObserverEntry' in window`, and
// `'intersectionRatio' in window.IntersectionObserverEntry.prototype` — jsdom has neither global
// at all (confirmed live), so stubbing only the constructor above still tripped the same
// unsupported-browser fallback via this second missing check. The `in` check inspects the
// PROTOTYPE specifically — a class field (`intersectionRatio = 0` in the constructor) lives on
// each instance, not the prototype, and silently fails this exact check (confirmed live); an
// explicit `prototype.intersectionRatio` assignment is required.
class NoopIntersectionObserverEntry {
  // `declare` — a type-only field declaration (no runtime per-instance initialization), so the
  // prototype assignment below is the sole place this property is actually ever set.
  declare intersectionRatio: number;
}
NoopIntersectionObserverEntry.prototype.intersectionRatio = 0;

